for code, v in E.items():
    T['erreurs.' + code] = v

def nest(i):
    out = {}
    for k, v in sorted(T.items()):
        parts = k.split('.')
        cur = out
        for p in parts[:-1]:
            cur = cur.setdefault(p, {})
        cur[parts[-1]] = v[i]
    return out

if __name__ == '__main__':
    base = os.path.join(os.path.dirname(__file__), '..', 'src', 'i18n')
    for i, lg in enumerate(['fr', 'en', 'zh']):
        with open(os.path.join(base, f'{lg}.json'), 'w', encoding='utf-8') as fh:
            json.dump(nest(i), fh, ensure_ascii=False, indent=1, sort_keys=True)
    print(len(T), 'clés')
